<?php
require_once __DIR__.'/sesion_segura.php';iniciar_sesion_segura();if(empty($_SESSION['usuario'])){header('Location: ./login.php');exit();}require_once './csrf.php';require_once './conexion.php';require_once './validacion_calidad.php';require_once './bitacora_helper.php';require_once './alertify_error.php';if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: control_calidad.php');exit();}validar_token_csrf_post();$db=conexion();
try{$db->begin_transaction();$datos=validar_datos_control_calidad($_POST);$operador_id=obtener_operador_calidad($db,(string)$_SESSION['usuario']);$stmt=$db->prepare('SELECT id FROM cosechas WHERE id=? FOR UPDATE');$stmt->bind_param('i',$datos['cosecha_id']);$stmt->execute();$cosecha=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$cosecha)throw new InvalidArgumentException('La cosecha seleccionada no existe.');
if($datos['producto_id']!==null){$stmt=$db->prepare('SELECT id FROM inventario_derivado WHERE id=? AND cosecha_id=?');$stmt->bind_param('ii',$datos['producto_id'],$datos['cosecha_id']);$stmt->execute();$producto=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$producto)throw new InvalidArgumentException('El producto debe pertenecer a la cosecha seleccionada.');}
$stmt=$db->prepare('INSERT INTO controles_calidad (cosecha_id,inventario_derivado_id,tipo_control,fecha_control,resultado,valor,unidad,observaciones,operador_id) VALUES (?,?,?,?,?,?,?,?,?)');$stmt->bind_param('iisssdssi',$datos['cosecha_id'],$datos['producto_id'],$datos['tipo_control'],$datos['fecha_control'],$datos['resultado'],$datos['valor'],$datos['unidad'],$datos['observaciones'],$operador_id);$stmt->execute();$control_id=(int)$db->insert_id;$stmt->close();registrar_evento_bitacora($db,$operador_id,'calidad','Crear','controles_calidad',$control_id,null,$datos);$db->commit();$db->close();header('Location: control_calidad.php?success=add');exit();}catch(Throwable $e){$db->rollback();$db->close();redirigir_excepcion_alertify($e,'No se pudo guardar el control de calidad.');}
